const fs = require('fs');
const path = require('path');

const backendDir = 'c:/Users/admin/Desktop/billing_inventory/backend';
const files = fs.readdirSync(backendDir).filter(f => f.startsWith('edits-') && f.endsWith('.json'));

const workspaceRoot = 'c:\\users\\admin\\desktop\\billing_inventory';

// We want to restore files that belong to the workspace
const workspaceEdits = [];

for (const file of files) {
  const filePath = path.join(backendDir, file);
  const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));

  data.forEach(edit => {
    if (edit.args && edit.args.TargetFile) {
      const targetFileLower = edit.args.TargetFile.toLowerCase();
      if (targetFileLower.startsWith(workspaceRoot.toLowerCase()) && !targetFileLower.includes('implementation_plan.md') && !targetFileLower.includes('task.md') && !targetFileLower.includes('walkthrough.md')) {
        workspaceEdits.push({
          editJsonFile: file,
          step_index: edit.step_index,
          name: edit.name,
          args: edit.args
        });
      }
    }
  });
}

// Sort all edits globally by step_index to apply them in the exact order they were executed
workspaceEdits.sort((a, b) => a.step_index - b.step_index);

console.log(`Loaded ${workspaceEdits.length} edits targeting workspace files.`);

// Group edits by file to see what we're modifying
const fileEdits = {};
workspaceEdits.forEach(e => {
  const f = e.args.TargetFile;
  if (!fileEdits[f]) fileEdits[f] = [];
  fileEdits[f].push(e);
});

console.log('\nEdits per file:');
for (const f in fileEdits) {
  console.log(`- ${f}: ${fileEdits[f].length} edits`);
}

// Helper to normalize line endings
function normalize(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/\r\n/g, '\n');
}

// Dry run
console.log('\n--- STARTING DRY RUN ---');
let dryRunSuccess = true;

// Keep in-memory file contents
const fileContents = {};

for (const edit of workspaceEdits) {
  const filePath = edit.args.TargetFile;
  if (!fileContents[filePath]) {
    if (!fs.existsSync(filePath)) {
      console.log(`[Dry Run] File does not exist, creating empty: ${filePath}`);
      fileContents[filePath] = '';
    } else {
      fileContents[filePath] = normalize(fs.readFileSync(filePath, 'utf-8'));
    }
  }

  let content = fileContents[filePath];
  console.log(`[Step ${edit.step_index}] Applying ${edit.name} to ${path.basename(filePath)}`);

  if (edit.name === 'replace_file_content') {
    const target = normalize(edit.args.TargetContent);
    const replacement = normalize(edit.args.ReplacementContent);

    const index = content.indexOf(target);
    if (index === -1) {
      console.error(`❌ Target content not found in ${path.basename(filePath)} at step ${edit.step_index}`);
      console.error(`Expected target snippet (first 100 chars):\n${target.substring(0, 100)}...`);
      dryRunSuccess = false;
    } else {
      // Check if it's unique
      const lastIndex = content.lastIndexOf(target);
      if (index !== lastIndex && !edit.args.AllowMultiple) {
        console.warn(`⚠️ Warning: Target content is not unique in ${path.basename(filePath)} at step ${edit.step_index}`);
      }
      content = content.replace(target, replacement);
      fileContents[filePath] = content;
    }
  } else if (edit.name === 'multi_replace_file_content') {
    const chunks = edit.args.ReplacementChunks;
    for (let c = 0; c < chunks.length; c++) {
      const chunk = chunks[c];
      const target = normalize(chunk.TargetContent);
      const replacement = normalize(chunk.ReplacementContent);

      const index = content.indexOf(target);
      if (index === -1) {
        console.error(`❌ Chunk #${c + 1} target content not found in ${path.basename(filePath)} at step ${edit.step_index}`);
        console.error(`Expected target snippet:\n${target.substring(0, 100)}...`);
        dryRunSuccess = false;
      } else {
        content = content.replace(target, replacement);
      }
    }
    fileContents[filePath] = content;
  } else if (edit.name === 'write_to_file') {
    const newContent = normalize(edit.args.CodeContent);
    fileContents[filePath] = newContent;
  }
}

if (dryRunSuccess) {
  console.log('\n✅ Dry run SUCCESSFUL! All targets matched and replaced successfully in memory.');
} else {
  console.log('\n❌ Dry run FAILED. Some targets were not found.');
}
